input.command:
cd ~ && KEY=$(grep -E "MYLYNX_API_KEY" ~/.dsh/.credentials.yaml | head -1 | sed -E 's/.*MYLYNX_API_KEY[^:]*:[[:space:]]*//; s/^["'"'"']//; s/["'"'"']$//'); curl -s -m 60 -o /dev/null -w "models:%{http_code}
" http://localhost:20128/v1/models -H "Authorization: Bearer $KEY"; curl -s -m 60 -w "
msgs:%{http_code}
" http://localhost:20128/v1/messages -H "x-api-key: $KEY" -H "Authorization: Bearer $KEY" -H "anthropic-version: 2023-06-01" -H "content-type: application/json" -d '{"model":"lynx harness","max_tokens":30,"messages":[{"role":"user","content":"Say hi"}]}' | head -c 600; curl -s -m 60 -w "
chat:%{http_code}
" http://localhost:20128/v1/chat/completions -H "Authorization: Bearer $KEY" -H "content-type: application/json" -d '{"model":"lynx harness","max_tokens":20,"messages":[{"role":"user","content":"Say hi"}]}' | head -c 400
